<template>
 <section class="investment-dashboard" aria-label="全库存投资决策">
  <div class="heading"><div><h2>全库存投资决策</h2><p>{{ decision.evidence.campaign?.title || '未关联广告实验' }} · {{ sourceSheet }} · {{ decision.coverage.total }} 块屏幕</p></div><button :disabled="dirty||busy" @click="$emit('export')">导出逐屏投资方案</button></div>
  <p class="scenario-label">{{ decision.scenario_label }}</p>
  <p v-if="dirty" class="stale">输入已变更，当前展示为上次计算结果。</p>
  <div class="kpis"><div><small>建议投入 · {{ currency }}</small><b>{{ money(decision.allocation.total) }}</b><span>{{ decision.allocation.screen_count }} 块 · {{ decision.allocation.budget_only?'预算级建议':'按输入周期估算' }}</span></div><div><small>保留预算</small><b>{{ money(decision.allocation.remaining) }}</b><span>探索投入 {{ money(decision.allocation.exploration) }}</span></div><div><small>直接模拟覆盖</small><b>{{ decision.coverage.direct }} / {{ decision.coverage.total }}</b><span>{{ decision.coverage.attitude }} 块具有双维态度评分</span></div><div><small>基准 ROI / ROAS</small><b>{{ pct(decision.returns.base?.roi) }} / {{ multiple(decision.returns.base?.roas) }}</b><span>{{ decision.returns.base?'基于填写的增量转化假设':'补齐转化、客单价、毛利及归因假设' }}</span></div></div>
  <p>重要度用于排序，分配金额另受成本、SOT、单屏与探索上限约束。模拟态度不是购买率；库存曝光和模拟曝光分列。所有 {{ decision.coverage.total }} 条记录均可查看，未分配的屏幕也保留原因。</p>
  <div class="filters"><input v-model="query" aria-label="搜索投资屏幕" placeholder="屏幕 ID / 地址"><select v-model="filter" aria-label="投资状态筛选"><option value="all">全部屏幕</option><option value="chosen">建议投入</option><option value="missing">缺少直接模拟</option><option value="excluded">库存排除</option></select><select v-model="sort" aria-label="投资排序"><option value="rank">重要度排序</option><option value="amount">投入金额排序</option><option value="interest">兴趣排序</option><option value="favorability">好感排序</option></select><span>{{ filtered.length }} 条</span></div>
  <div class="table-scroll"><table><thead><tr><th>重要度 / 排名</th><th>屏幕 / 地址</th><th>库存机会<br>全 SOT / 规划周期</th><th>模拟机会<br>原模拟周期</th><th>好感 / 兴趣<br>0–100</th><th>建议投入<br>{{ currency }}</th><th>SOT</th><th>基准 ROI</th><th>建议</th></tr></thead><tbody><tr v-for="r in pageRows" :key="r.key"><td><b>{{ fixed(r.importance) }}</b><small>#{{ r.rank||'—' }}</small></td><td><button class="screen" @click="selected=r">{{ r.address || r.screen_id }}</button><small>{{ r.screen_id }}</small></td><td>{{ count(r.inventory_exposures) }}</td><td>{{ count(r.sim?.total) }}<small v-if="r.sim">{{ r.sim.hours }}h · 评分覆盖 {{ pct(r.sim.interest_coverage) }}</small></td><td>{{ fixed(r.sim?.favorability) }} / {{ fixed(r.sim?.interest) }}</td><td><b>{{ money(r.recommended_amount) }}</b><small>预算 {{ pct(r.budget_share) }}</small></td><td>{{ pct(r.recommended_sot) }}</td><td>{{ pct(r.returns?.base?.roi) }}</td><td><span :class="{picked:r.recommended_amount>0}">{{ r.status }}</span><button class="text-button" @click="selected=r">依据 →</button></td></tr></tbody></table></div>
  <div class="pager"><button :disabled="page<=1" @click="page--">上一页</button><span>{{ page }} / {{ pages }}</span><button :disabled="page>=pages" @click="page++">下一页</button></div>
  <details><summary>方案回报区间与计算口径</summary><div class="return-grid"><article v-for="(label,key) in scenarios" :key="key"><h3>{{ label }}情景</h3><p>增量收入 {{ money(decision.returns[key]?.revenue) }} {{ currency }}</p><p>扣广告费后贡献 {{ money(decision.returns[key]?.profit) }}</p><p>ROI {{ pct(decision.returns[key]?.roi) }} · ROAS {{ multiple(decision.returns[key]?.roas) }}</p></article></div><ul><li v-for="s in decision.assumptions" :key="s">{{ s }}</li></ul></details>
  <ModalWindow v-model="opened" title="逐屏投资依据" :subtitle="selected?.address">
   <template v-if="selected"><p>{{ selected.screen_id }}</p><div class="kpis"><div><small>重要度与未知敏感性范围</small><b>{{ fixed(selected.importance) }}</b><span>{{ fixed(selected.importance_low) }}–{{ fixed(selected.importance_high) }}，非置信区间</span></div><div><small>建议金额 / SOT</small><b>{{ money(selected.recommended_amount) }}</b><span>{{ currency }} · {{ pct(selected.recommended_sot) }}</span></div></div><p class="reason">{{ selected.reason }}</p>
   <div class="table-scroll"><table><thead><tr><th>维度</th><th>分数</th><th>权重</th><th>口径</th></tr></thead><tbody><tr v-for="(label,key) in labels" :key="key"><td>{{ label }}</td><td>{{ fixed(selected.dimensions[key]) }}</td><td>{{ pct(decision.config.weights[key]) }}</td><td>{{ selected.unknown_dimensions.includes(key)?'缺少证据，重要度使用中性先验':'库存推导 / 直接模拟推断，非实测效果' }}</td></tr></tbody></table></div>
   <p v-if="selected.sim">原模拟 {{ selected.sim.hours }}h：行人 {{ count(selected.sim.pedestrian) }}、车内 {{ count(selected.sim.vehicle) }} 次机会；{{ selected.sim.representatives }} 个代表画像。高好感 {{ count(selected.sim.high_favorability) }}、高兴趣 {{ count(selected.sim.high_interest) }}、同时达到阈值 {{ count(selected.sim.joint_high) }} 次。阈值 {{ decision.config.threshold }}，重复经过仍计次。</p>
   <p v-if="selected.peak.length">建议对照试投时段：{{ selected.peak.map(h=>`第${h.day}天 ${h.time}`).join(' / ') }}；仅按模拟机会排序，尚未模拟分时购买价格。</p><p v-else>此屏幕缺少模拟时段证据，先完成本地点仿真或取得实测客流。</p>
   <h3>试投验证安排</h3><p>{{ selected.test_action }}</p><h3>当前建议金额下的回报情景</h3><div class="return-grid"><article v-for="(label,key) in scenarios" :key="key"><h4>{{ label }}</h4><p>收入 {{ money(selected.returns?.[key]?.revenue) }}</p><p>贡献 {{ money(selected.returns?.[key]?.profit) }}</p><p>ROI {{ pct(selected.returns?.[key]?.roi) }}</p><p>ROAS {{ multiple(selected.returns?.[key]?.roas) }}</p></article></div><p>广告费保本需 {{ fixed(selected.returns?.break_even_per_thousand,3) }} 单 / 千次曝光（按归因前转化假设口径）。{{ selected.returns?.rate_source }}；{{ decision.config.roi.source }}</p>
   <details><summary>数据缺口与风险</summary><ul><li v-for="w in selected.warnings" :key="w">{{ w }}</li></ul><p>证据指纹：{{ decision.evidence.fingerprint||'未关联' }}</p></details></template>
  </ModalWindow>
 </section>
</template>
<script setup>
import {computed,ref,watch} from 'vue'
import ModalWindow from './ModalWindow.vue'
const props=defineProps({decision:Object,currency:String,sourceSheet:String,dirty:Boolean,busy:Boolean})
defineEmits(['export'])
const query=ref(''),filter=ref('all'),sort=ref('amount'),page=ref(1),selected=ref(null)
const opened=computed({get:()=>!!selected.value,set:v=>{if(!v)selected.value=null}})
const filtered=computed(()=>props.decision.rows.filter(r=>`${r.screen_id} ${r.address}`.toLowerCase().includes(query.value.toLowerCase())&&(filter.value==='all'||filter.value==='chosen'&&r.recommended_amount>0||filter.value==='missing'&&!r.sim||filter.value==='excluded'&&!r.eligible)).sort((a,b)=>sort.value==='amount'?b.recommended_amount-a.recommended_amount:sort.value==='rank'?(a.rank??Infinity)-(b.rank??Infinity):(b.sim?.[sort.value]??-1)-(a.sim?.[sort.value]??-1)))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/12))),pageRows=computed(()=>filtered.value.slice((page.value-1)*12,page.value*12))
watch([query,filter,sort],()=>page.value=1);watch(()=>props.decision,()=>{page.value=1;selected.value=null})
const labels={exposure:'曝光',favorability:'好感',interest:'兴趣',visibility:'可见性',location:'位置',market:'市场匹配',cost:'成本'},scenarios={low:'保守',base:'基准',high:'乐观'}
const fixed=(n,d=1)=>n==null?'未知':Number(n).toFixed(d),pct=n=>n==null?'未知':(n*100).toFixed(1)+'%',multiple=n=>n==null?'未知':n.toFixed(2)+'×'
const money=n=>n==null?'未知':Number(n).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}),count=n=>n==null?'未知':Math.round(n).toLocaleString('zh-CN')
</script>
<style scoped>
.investment-dashboard{background:white;border:1px solid #dae3dc;border-radius:12px;padding:22px;margin-bottom:20px;color:#23362b;font-size:12px}.heading,.filters,.pager{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}h2{font-size:20px;margin:0}h3{font-size:14px}p,li{font-size:12px;line-height:1.9;color:#617267}.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:18px 0}.kpis>div{background:#f3f8f5;border-radius:8px;padding:14px}.kpis b{font-size:23px;display:block;margin:7px 0;color:#263f30}.kpis small,.kpis span{font-size:10px;display:block;line-height:1.7}.filters input{flex:1;min-width:180px}input,select,button{font:inherit;border:1px solid #c9d9cd;border-radius:5px;padding:8px;background:white;color:#295b42}button{cursor:pointer}button:disabled{opacity:.4;cursor:default}.table-scroll{overflow:auto;margin:16px 0;max-height:620px}table{border-collapse:collapse;width:100%;font-size:11px}th,td{text-align:left;vertical-align:top;padding:12px 8px;border-bottom:1px solid #e5ece6;min-width:65px}th{white-space:nowrap;background:#f7faf8;position:sticky;top:0}td small{display:block;color:#738478;font-size:9px;margin-top:5px;max-width:150px;overflow-wrap:anywhere}.screen{text-align:left;border:0;padding:0;min-width:140px;max-width:200px}.text-button{display:block;border:0;padding:4px 0;font-size:10px}.picked{color:#186a4a}.pager{justify-content:center}.return-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.return-grid article{background:#f5f8f6;padding:12px;border-radius:7px}.return-grid h3,.return-grid h4{margin:0}.return-grid p{font-size:11px}summary{cursor:pointer;padding:12px 0}ul{padding-left:18px}.reason,.stale{background:#f6f2e6;padding:12px;border-radius:6px}li{margin:8px 0}@media(max-width:1100px){.kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.investment-dashboard{padding:14px}.return-grid{grid-template-columns:1fr}.kpis b{font-size:19px}}
</style>
